WITH base AS (SELECT *, CEIL(amount) AS amount_whole, LOWER(merchant) AS merchant_lower, COALESCE(merchant, 'NONE') AS resolved_merchant FROM transactions WHERE merchant IS NOT NULL AND txn_time >= TO_TIMESTAMP('2023-10-03 05:00:00')), with_gaps AS (SELECT *, CASE WHEN LAG(txn_time) OVER (PARTITION BY txn_type ORDER BY txn_time, id) IS NULL OR txn_time > LAG(txn_time) OVER (PARTITION BY txn_type ORDER BY txn_time, id) + INTERVAL 60 DAYS THEN 1 ELSE 0 END AS session_start_flag FROM base), sessionized AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY txn_type ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM with_gaps) SELECT merchant, SUM(session_start_flag) FILTER (WHERE txn_type = 'REFUND') AS refund_total_session_start_flag, MAX(txn_time) AS last_txn_time, MIN(txn_time) AS first_seen FROM sessionized GROUP BY merchant ORDER BY refund_total_session_start_flag DESC
